  "test_path": "tests/unit/test_observe_output_env.py",
  "test": "import os
import pytest
from langfuse import observe
from langfuse._client.observe import _ContextPreservedSyncGeneratorWrapper
from langfuse._client.attributes import LangfuseOtelSpanAttributes

@pytest.mark.asyncio
async def test_output_capture_respects_env_var(langfuse_memory_client: Any, memory_exporter: Any, monkeypatch: Any) -> None:
    # Disable output capture via environment variable
    monkeypatch.setenv("LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED", "False")
    # Ensure the generic I/O capture env var is left at its default (True) for this test
    monkeypatch.delenv("LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED", raising=False)

    @observe(name="env_span")
    def fn() -> dict:
        return {"x": 1}

    result = fn()
    assert result == {"x": 1}

    langfuse_memory_client.flush()
    spans = [s for s in memory_exporter.get_finished_spans() if s.name == "env_span"]
    assert len(spans) == 1
    span = spans[0]
    # Output should not be recorded because the env var disabled it
    assert LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT not in span.attributes"
}
